window.docContents[146].resolve({"/MoreStlc/#Type-Systems--MoreStlc___-More-on-the-Simply-Typed-Lambda-Calculus--Simple-Extensions-to-STLC":{"contents":"The simply typed lambda-calculus has a rich enough structure to make\nits theoretical properties interesting, but it is not much of a\nprogramming language!\n\nIn this chapter, we begin to close the gap with real-world languages by\nintroducing a number of familiar features that have straightforward\ntreatments at the level of typing.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009MoreStlc: More on the Simply Typed Lambda-Calculus","header":"7.1. Simple Extensions to STLC","id":"/MoreStlc/#Type-Systems--MoreStlc___-More-on-the-Simply-Typed-Lambda-Calculus--Simple-Extensions-to-STLC"}});